var app=angular.module("kycApp",[]);
app.service("kycService",["$http",function($http){var protocal=window.location.protocol;
var host=window.location.host;
var uRl=protocal+"//"+host+"/";
this.createKYCRecord=function(kycRecord){return $http.post(uRl+"kyc",kycRecord)};
this.getKYCRecordById=function(id){return $http.get(uRl+"kyc/"+id)};
this.kycRecordInActive=function(id,accessingId){return $http.get(uRl+"kyc/kycRecordInActive/"+id+"/"+accessingId)};
this.kycRecordActive=function(id,accessingId){return $http.get(uRl+"kyc/kycRecordActive/"+id+"/"+accessingId)};
this.getAllKycRecords=function(){return $http.get(uRl+"kyc")};
this.getAllKYCRecords=function(userName){return $http.get(uRl+"kyc/getList/"+userName)};
this.updateKYCRecord=function(id,kycRecord){return $http.put(uRl+"kyc/"+id,kycRecord)};
this.deleteKYCRecord=function(id){return $http.delete(uRl+"kyc/"+id)};
this.getKycRecordsByAadharNo=function(adharNo){return $http.get(uRl+"kyc/getAadhar/"+adharNo)}}]);